# Program three: a decision. Seven against a threshold; where it
# lands depends on a number in this file, not on any code.
statics
  0 = "LOW_PATH"
  1 = "HIGH_PATH"
  2 = 5

head seven p
  out 0 - decide.0

decide keep c
  in 1 $2
  out 0 - low.1
  out 2 - high.1

low write_int_file p
  in 0 $0

high write_int_file p
  in 0 $1
